window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d4c53a77c5e70962"]={"versions": [{"id": "FIG-d4c53a77c5e70962", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm / Schnittstellendiagramm (AUTOSAR Adaptive Platform Architekturmodell).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform R23-11, Spezifikation <code>AUTOSAR_AP_SWS_LogAndTrace</code> (Kapitel 5.2 <em>Required Interfaces</em>).\n</li><li><strong>Technischer Zweck:</strong> Spezifiziert die normativen und plattforminternen Abhängigkeiten des Functional Clusters (FC) <strong>Log and Trace</strong> gegenüber anderen Komponenten der Adaptive Platform und dem Basisbetriebssystem:\n<ul class=\"fig-list\"><li>Bezug hochpräziser, global synchronisierter Zeitstempel für DLT-Logging-Pakete (Diagnostic Log and Trace).\n</li><li>Socket-basierter Export von DLT-Streams an externe Clients/Tester über das Netzwerk.\n</li><li>Lokale Persistierung von Trace- und Log-Puffern in nicht-flüchtigen Speichern.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Functional Clusters</h5>\n<ul class=\"fig-list\"><li><strong><code>«aapFunctionalCluster» Log and Trace</code>:</strong> Konsumenten-Cluster; aggregiert, filtert und serialisiert standardisierte Log-Meldungen von Applikationen und Plattform-Clustern.\n</li><li><strong><code>«aapFunctionalCluster» Time Synchronization</code> (mit Annotation <code>daemon-based</code>):</strong> Stellt über einen Hintergrunddienst (Daemon) synchronisierte Zeitbasen (z. B. IEEE 802.1AS / gPTP) bereit.\n</li><li><strong><code>Operating System</code>:</strong> Host-Betriebssystem (POSIX PSE51/52/53-kompatibel), welches grundlegende System- und I/O-Dienste bereitstellt.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>«aapAPI,aapPortInterface» Time Synchronization::SynchronizedTimeBaseConsumer</code>:</strong>\n<ul class=\"fig-list\"><li>Normative Schnittstelle des Required Ports (<code>«aapRequiredPort»</code>) von Log and Trace.\n</li><li><em>Synchrone Methoden:</em>\n<ul class=\"fig-list\"><li><code>+ GetCurrentTime()</code>\n</li><li><code>+ GetRateDeviation()</code>\n</li><li><code>+ GetTimeWithStatus(): SynchronizedTimeBaseStatus</code>\n</li></ul>\n</li><li><em>Asynchrone Registrierungen / Deregistrierungen:</em>\n<ul class=\"fig-list\"><li><code>+ RegisterStatusChangeNotifier()</code> / <code>+ UnregisterStatusChangeNotifier()</code>\n</li><li><code>+ RegisterSynchronizationStateChangeNotifier()</code> / <code>+ UnregisterSynchronizationStateChangeNotifier()</code>\n</li><li><code>+ RegisterTimeLeapNotifier()</code> / <code>+ UnregisterTimeLeapNotifier()</code>\n</li><li><code>+ RegisterTimePrecisionMeasurementNotifier()</code> / <code>+ UnregisterTimePrecisionMeasurementNotifier()</code>\n</li><li><code>+ RegisterTimeValidationNotification()</code> / <code>+ UnregisterTimeValidationNotification()</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>«aapInternal» TCP/IP Stack</code>:</strong> Plattform-/OS-interne Netzwerkschnittstelle (Standard-Socket-Interface).\n</li><li><strong><code>«aapInternal» Non-volatile Storage</code>:</strong> Plattform-/OS-interne Schnittstelle für nicht-flüchtigen Speicher (Dateisystem/Flash-Storage).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong><code>Log and Trace</code> → <code>SynchronizedTimeBaseConsumer</code>:</strong> Abhängigkeitsbeziehung <code>«use»</code> über einen <code>«aapRequiredPort»</code>.\n</li><li><strong><code>Time Synchronization</code> → <code>SynchronizedTimeBaseConsumer</code>:</strong> Realisierungsbeziehung (gestrichelte Linie mit geschlossener Dreiecksspitze).\n</li><li><strong><code>Log and Trace</code> → <code>TCP/IP Stack</code> &amp; <code>Non-volatile Storage</code>:</strong> Abhängigkeitsbeziehungen <code>«use»</code>.\n</li><li><strong><code>Operating System</code> → <code>TCP/IP Stack</code> &amp; <code>Non-volatile Storage</code>:</strong> Realisierungsbeziehungen des Basisbetriebssystems.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierungsphase:</strong>\n<ul class=\"fig-list\"><li><em>Log and Trace</em> bindet den Port <code>SynchronizedTimeBaseConsumer</code>.\n</li><li>Registrierung relevanter Notifier (<code>RegisterSynchronizationStateChangeNotifier</code>, <code>RegisterTimeLeapNotifier</code>), um Statusübergänge der Synchronisation oder Sprünge der Zeitbasis (Leaps) asynchron zu erfassen.\n</li></ul>\n</li><li><strong>Laufzeit / Log-Generierung (Synchroner Pfad):</strong>\n<ul class=\"fig-list\"><li>Beim Eintreffen eines Log-Events liest <em>Log and Trace</em> synchron via <code>GetCurrentTime()</code> bzw. <code>GetTimeWithStatus()</code> den Zeitstempel und dessen Gültigkeitsstatus aus.\n</li><li>Der Zeitstempel wird in den DLT-Standard-Header eingebettet.\n</li></ul>\n</li><li><strong>Ausnahme-/Drift-Handling (Asynchroner Callback):</strong>\n<ul class=\"fig-list\"><li>Tritt ein Zeitsprung auf, feuert der Callback von <code>RegisterTimeLeapNotifier()</code>. <em>Log and Trace</em> aktualisiert intern die Referenzzeit oder vermerkt den Synchronisationsverlust im Metadaten-Stream, um Monotoniebrüche im Trace analysierbar zu machen.\n</li></ul>\n</li><li><strong>Export &amp; Speicherung:</strong>\n<ul class=\"fig-list\"><li>DLT-Streams werden über POSIX-Sockets des <code>TCP/IP Stack</code> (UDP/TCP) an externe Logging-Tools gestreamt.\n</li><li>Bei konfigurierter lokaler Protokollierung schreibt der DLT-Daemon die Log-Dateien blockweise oder ringgepuffert direkt auf den <code>Non-volatile Storage</code>.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Entkopplung über Port vs. Intern:</strong>\n<ul class=\"fig-list\"><li>Der Zugriff auf <code>Time Synchronization</code> erfolgt streng über das AUTOSAR Adaptive Port-Modell (<code>ara::ts</code>). Dies erfordert ein entsprechendes Service-Deployment und Port-Mapping im ARXML-Manifest.\n</li><li>Der Zugriff auf <code>TCP/IP Stack</code> und <code>Non-volatile Storage</code> ist als <code>«aapInternal»</code> deklariert. Dies bedeutet, dass <em>Log and Trace</em> nicht zwingend andere funktionale Cluster wie <code>ara::com</code> oder <code>ara::per</code> nutzt, sondern performanzkritisch direkt über native OS-Sockets und Standard-POSIX-Dateisystemaufrufe arbeiten darf/muss.\n</li></ul>\n</li><li><strong>Timing &amp; Performance im Logging-Pfad:</strong>\n<ul class=\"fig-list\"><li><code>GetCurrentTime()</code> liegt im direkten Ausführungspfad des Logging-APIs (<code>ara::log</code>). Implementierungen müssen sicherstellen, dass dieser Aufruf atomar, sperrarm (Lock-free/Shared Memory) und ohne Inter-Process-Context-Switches bedient wird, um Logging-Jitter zu minimieren.\n</li></ul>\n</li><li><strong>Fallback-Mechanismus bei Synchronisationsverlust:</strong>\n<ul class=\"fig-list\"><li>Liefert <code>GetTimeWithStatus()</code> einen ungültigen Status (<code>SynchronizedTimeBaseStatus</code> != SYNC) oder ist der Time Synchronization Daemon noch nicht initialisiert, muss die Implementierung auf eine lokale, monotone OS-Uhr (z. B. <code>CLOCK_MONOTONIC</code>) zurückfallen und das Flag im DLT-Header entsprechend kennzeichnen.\n</li></ul>\n</li><li><strong>Plattform- und Prozessrechte:</strong>\n<ul class=\"fig-list\"><li>Im POSIX-Prozessmodell müssen dem <em>Log and Trace</em>-Daemon ausreichende Dateisystem-Schreibrechte (Quota für NV-Speicher) sowie Socket-Berechtigungen (z. B. Binden an DLT-Port 3490) über die OS-Access-Control-Konfiguration zugewiesen werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2aa079613c75c7d3", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm / Schnittstellendiagramm (AUTOSAR Adaptive Platform Architekturmodell).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform R23-11, Spezifikation <code>AUTOSAR_AP_SWS_LogAndTrace</code> (Kapitel 5.2 <em>Required Interfaces</em>).\n</li><li><strong>Technischer Zweck:</strong> Spezifiziert die normativen und plattforminternen Abhängigkeiten des Functional Clusters (FC) <strong>Log and Trace</strong> gegenüber anderen Komponenten der Adaptive Platform und dem Basisbetriebssystem:\n<ul class=\"fig-list\"><li>Bezug hochpräziser, global synchronisierter Zeitstempel für DLT-Logging-Pakete (Diagnostic Log and Trace).\n</li><li>Socket-basierter Export von DLT-Streams an externe Clients/Tester über das Netzwerk.\n</li><li>Lokale Persistierung von Trace- und Log-Puffern in nicht-flüchtigen Speichern.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Functional Clusters</h5>\n<ul class=\"fig-list\"><li><strong><code>«aapFunctionalCluster» Log and Trace</code>:</strong> Konsumenten-Cluster; aggregiert, filtert und serialisiert standardisierte Log-Meldungen von Applikationen und Plattform-Clustern.\n</li><li><strong><code>«aapFunctionalCluster» Time Synchronization</code> (mit Annotation <code>daemon-based</code>):</strong> Stellt über einen Hintergrunddienst (Daemon) synchronisierte Zeitbasen (z. B. IEEE 802.1AS / gPTP) bereit.\n</li><li><strong><code>Operating System</code>:</strong> Host-Betriebssystem (POSIX PSE51/52/53-kompatibel), welches grundlegende System- und I/O-Dienste bereitstellt.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>«aapAPI,aapPortInterface» Time Synchronization::SynchronizedTimeBaseConsumer</code>:</strong>\n<ul class=\"fig-list\"><li>Normative Schnittstelle des Required Ports (<code>«aapRequiredPort»</code>) von Log and Trace.\n</li><li><em>Synchrone Methoden:</em>\n<ul class=\"fig-list\"><li><code>+ GetRateDeviation()</code>\n</li><li><code>+ GetTimeWithStatus(): SynchronizedTimeBaseStatus</code>\n</li></ul>\n</li><li><em>Asynchrone Registrierungen / Deregistrierungen:</em>\n<ul class=\"fig-list\"><li><code>+ RegisterStatusChangeNotifier()</code> / <code>+ UnregisterStatusChangeNotifier()</code>\n</li><li><code>+ RegisterSynchronizationStateChangeNotifier()</code> / <code>+ UnregisterSynchronizationStateChangeNotifier()</code>\n</li><li><code>+ RegisterTimeLeapNotifier()</code> / <code>+ UnregisterTimeLeapNotifier()</code>\n</li><li><code>+ RegisterTimePrecisionMeasurementNotifier()</code> / <code>+ UnregisterTimePrecisionMeasurementNotifier()</code>\n</li><li><code>+ RegisterTimeValidationNotification()</code> / <code>+ UnregisterTimeValidationNotification()</code>\n</li></ul>\n</li></ul>\n</li><li><strong><code>«aapInternal» TCP/IP Stack</code>:</strong> Plattform-/OS-interne Netzwerkschnittstelle (Standard-Socket-Interface).\n</li><li><strong><code>«aapInternal» Non-volatile Storage</code>:</strong> Plattform-/OS-interne Schnittstelle für nicht-flüchtigen Speicher (Dateisystem/Flash-Storage).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong><code>Log and Trace</code> → <code>SynchronizedTimeBaseConsumer</code>:</strong> Abhängigkeitsbeziehung <code>«use»</code> über einen <code>«aapRequiredPort»</code>.\n</li><li><strong><code>Time Synchronization</code> → <code>SynchronizedTimeBaseConsumer</code>:</strong> Realisierungsbeziehung (gestrichelte Linie mit geschlossener Dreiecksspitze).\n</li><li><strong><code>Log and Trace</code> → <code>TCP/IP Stack</code> &amp; <code>Non-volatile Storage</code>:</strong> Abhängigkeitsbeziehungen <code>«use»</code>.\n</li><li><strong><code>Operating System</code> → <code>TCP/IP Stack</code> &amp; <code>Non-volatile Storage</code>:</strong> Realisierungsbeziehungen des Basisbetriebssystems.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialisierungsphase:</strong>\n<ul class=\"fig-list\"><li><em>Log and Trace</em> bindet den Port <code>SynchronizedTimeBaseConsumer</code>.\n</li><li>Registrierung relevanter Notifier (<code>RegisterSynchronizationStateChangeNotifier</code>, <code>RegisterTimeLeapNotifier</code>), um Statusübergänge der Synchronisation oder Sprünge der Zeitbasis (Leaps) asynchron zu erfassen.\n</li></ul>\n</li><li><strong>Laufzeit / Log-Generierung (Synchroner Pfad):</strong>\n<ul class=\"fig-list\"><li>Beim Eintreffen eines Log-Events liest <em>Log and Trace</em> synchron via <code>GetTimeWithStatus()</code> den Zeitstempel und dessen Synchronisationsstatus aus.\n</li><li>Der Zeitstempel wird in den DLT-Standard-Header eingebettet.\n</li></ul>\n</li><li><strong>Ausnahme-/Drift-Handling (Asynchroner Callback):</strong>\n<ul class=\"fig-list\"><li>Tritt ein Zeitsprung auf, feuert der Callback von <code>RegisterTimeLeapNotifier()</code>. <em>Log and Trace</em> aktualisiert intern die Referenzzeit oder vermerkt den Synchronisationsverlust im Metadaten-Stream, um Monotoniebrüche im Trace analysierbar zu machen.\n</li></ul>\n</li><li><strong>Export &amp; Speicherung:</strong>\n<ul class=\"fig-list\"><li>DLT-Streams werden über POSIX-Sockets des <code>TCP/IP Stack</code> (UDP/TCP) an externe Logging-Tools gestreamt.\n</li><li>Bei konfigurierter lokaler Protokollierung schreibt der DLT-Daemon die Log-Dateien blockweise oder ringgepuffert direkt auf den <code>Non-volatile Storage</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Entkopplung über Port vs. Intern:</strong>\n<ul class=\"fig-list\"><li>Der Zugriff auf <code>Time Synchronization</code> erfolgt streng über das AUTOSAR Adaptive Port-Modell (<code>ara::ts</code>). Dies erfordert ein entsprechendes Service-Deployment und Port-Mapping im ARXML-Manifest.\n</li><li>Der Zugriff auf <code>TCP/IP Stack</code> und <code>Non-volatile Storage</code> ist als <code>«aapInternal»</code> deklariert. Dies bedeutet, dass <em>Log and Trace</em> nicht zwingend andere funktionale Cluster wie <code>ara::com</code> oder <code>ara::per</code> nutzt, sondern performanzkritisch direkt über native OS-Sockets und Standard-POSIX-Dateisystemaufrufe arbeiten darf/muss.\n</li></ul>\n</li><li><strong>Timing &amp; Performance im Logging-Pfad:</strong>\n<ul class=\"fig-list\"><li><code>GetTimeWithStatus()</code> liegt im direkten Ausführungspfad des Logging-APIs (<code>ara::log</code>). Implementierungen müssen sicherstellen, dass dieser Aufruf atomar, sperrarm (Lock-free/Shared Memory) und ohne Inter-Process-Context-Switches bedient wird, um Logging-Jitter zu minimieren.\n</li></ul>\n</li><li><strong>Fallback-Mechanismus bei Synchronisationsverlust:</strong>\n<ul class=\"fig-list\"><li>Liefert <code>GetTimeWithStatus()</code> einen ungültigen Status (<code>SynchronizedTimeBaseStatus</code> != SYNC) oder ist der Time Synchronization Daemon noch nicht initialisiert, muss die Implementierung auf eine lokale, monotone OS-Uhr (z. B. <code>CLOCK_MONOTONIC</code>) zurückfallen und das Flag im DLT-Header entsprechend kennzeichnen.\n</li></ul>\n</li><li><strong>Plattform- und Prozessrechte:</strong>\n<ul class=\"fig-list\"><li>Im POSIX-Prozessmodell müssen dem <em>Log and Trace</em>-Daemon ausreichende Dateisystem-Schreibrechte (Quota für NV-Speicher) sowie Socket-Berechtigungen (z. B. Binden an DLT-Port 3490) über die OS-Access-Control-Konfiguration zugewiesen werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d4c53a77c5e70962", "to": "FIG-2aa079613c75c7d3", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Entfernung der Operation <code>+ GetCurrentTime()</code> aus dem Port-Interface <code>«aapAPI,aapPortInterface» Time Synchronization::SynchronizedTimeBaseConsumer</code>.\n</li><li>Zweizeiliger Umbruch der Schnittstellennamen <code>Time Synchronization::SynchronizedTimeBaseConsumer</code> und <code>Non-volatile Storage</code> (rein redaktionell/Layout).\n</li></ul>"}]};
